delete FROM PBC_SEND_ZIP_DAT_FILE F
where F.ZIP_SEND_STATUS = '01'
AND F.DAT_ZIP_TYPE = 'PI'
and F.DAT_ZIP_CODE = #{zipCode,jdbcType=VARCHAR}
and ORG_CODE = #{orgCode,jdbcType=VARCHAR}
